# librl -> libsk API parity map. Checked by tools/parity.sh (`make parity`).
#
# The goal is functional parity, not a 1:1 API: this file accounts for every librl
# function so nothing is forgotten, but a todo is resolved by designing the libsk
# way to do the same thing, not by copying the signature. One librl function may
# map to a differently shaped libsk function, be covered by another design, or be
# dropped once we decide it was a mistake.
#
# One line per librl public function that does NOT exist in libsk under the same
# suffix (rl_foo -> sk_foo is matched automatically and needs no entry):
#
#   rl_name  ported   sk_name   [note]   capability exists in libsk (sk_name covers it)
#   rl_name  dropped  reason             left out on purpose
#   rl_name  todo     [note]             not covered yet; needs a design decision
#
# Same-name matching only proves the function exists, not that it behaves the
# same; docs/TASKS.md tracks known behavior gaps.
#
# Keep entries grouped by header. Everything must fit the handle-only public API
# (see AGENTS.md).

# --- rl.h (core / lifecycle) ---
rl_deinit                               ported   sk_request_quit      sokol owns the loop; cleanup runs in the sk_set_cleanup callback
rl_init_values_async                    dropped  sk_run owns startup; async setup happens before the first frame
rl_get_delta_time                       dropped  timing is passed to the frame/tick callbacks (dt, tick_fraction)
rl_tick                                 ported   sk_set_frame         callback-driven loop instead of polling; sk_set_tick adds fixed-rate simulation

# --- rl_camera3d.h ---
rl_camera3d_set                         ported   sk_camera3d_set_view  plus set_projection / set_fov (radians) / set_ortho_height; fovy no longer doubles as ortho height

# --- rl_asset.h ---
rl_asset_ensure                         dropped  synchronous fetch needs JSPI on wasm; use sk_asset_ensure_async
rl_asset_ensure_many_async              ported   sk_asset_group_create + sk_asset_group_add (handle-only; members ensured separately) + sk_asset_get_progress
rl_asset_ensure_many_from_scratch_async dropped  scratch buffer
rl_asset_finish_task                    dropped  managed task queue fires callbacks (sk_asset_add_task)
rl_asset_free_task                      dropped  managed task queue frees tasks
rl_asset_get_task_path                  dropped  path is passed to the callback
rl_asset_ping_host                      todo     host latency: designed with the sk_net rework
rl_asset_poll_task                      dropped  managed task queue; callbacks instead of polling
rl_asset_tick                           dropped  runtime ticks the asset queue each frame (internal sk_asset_tick)

# --- rl_font.h ---
rl_font_destroy                         ported   sk_font_release      resources are reference counted: release drops this handle's reference
rl_font_get_default                     ported   sk_text_get_default_font   (0 = built in; sk_text_set_default_font replaces it)

# --- rl_fs.h (filesystem is internal in libsk; see docs/PLAN-sk_fs.md) ---
rl_fs_clear                             dropped  sk_fs is internal
rl_fs_deinit                            dropped  sk_fs is internal
rl_fs_deinit_async                      dropped  sk_fs is internal
rl_fs_exists                            dropped  sk_fs is internal
rl_fs_flush                             dropped  sk_fs is internal
rl_fs_get_root_dir                      dropped  sk_fs is internal
rl_fs_init                              dropped  sk_fs is internal
rl_fs_init_async                        dropped  sk_fs is internal
rl_fs_is_initialized                    dropped  sk_fs is internal
rl_fs_is_ready                          dropped  sk_fs is internal
rl_fs_mkdir                             dropped  sk_fs is internal
rl_fs_normalize_path                    dropped  sk_fs is internal
rl_fs_read                              dropped  sk_fs is internal; bytes never cross into user code
rl_fs_read_free                         dropped  sk_fs is internal
rl_fs_remove                            dropped  sk_fs is internal
rl_fs_restore_async                     dropped  sk_fs is internal
rl_fs_rmdir                             dropped  sk_fs is internal
rl_fs_write                             dropped  sk_fs is internal; bytes never cross into user code

# --- rl_input.h ---
rl_input_poll_events                    dropped  sokol_app delivers events via callbacks

# --- lighting (rl.h / rl_render.h): redesigned as light objects in scenes (docs/PLAN-lighting.md) ---
rl_disable_lighting                     ported   sk_light_set_enabled   per light, not global
rl_enable_lighting                      ported   sk_light_create        lighting comes from lights added to a scene
rl_is_lighting_enabled                  ported   sk_light_is_enabled
rl_set_light_ambient                    ported   sk_scene_set_ambient   per scene, with color
rl_set_light_direction                  ported   sk_light_set_direction

# --- rl_model.h ---
rl_model_create_from_file               dropped  objects are created from handles (sk_mesh_create + sk_model_create)
rl_model_destroy_asset                  ported   sk_mesh_release
rl_model_get_animation_frame_count      ported   sk_model_get_animation_duration  glTF animations are timed in seconds, not frames
rl_model_get_default_asset              dropped  no placeholder model: a model without a mesh draws nothing (missing images get sk_texture_get_placeholder)
rl_model_is_valid                       ported   sk_model_is_ready  handles are generation-checked; the question is whether a mesh is loaded
rl_model_is_valid_strict                ported   sk_model_is_ready  one readiness check
rl_model_load_asset                     ported   sk_mesh_create
rl_model_set_asset                      ported   sk_model_set_mesh
rl_model_update_animation               ported   sk_model_set_animation_time  pose at a time in seconds (set the clip with sk_model_set_animation)

# --- rl_music.h (music is a looping Sound over an Audio) ---
rl_music_create                         dropped  sk_audio_create + sk_sound_create
rl_music_destroy                        dropped  sk_sound_destroy
rl_music_is_playing                     dropped  sk_sound_is_playing
rl_music_pause                          dropped  sk_sound_pause
rl_music_play                           dropped  sk_sound_play
rl_music_set_loop                       dropped  sk_sound_set_loop
rl_music_set_volume                     dropped  sk_sound_set_volume
rl_music_stop                           dropped  sk_sound_stop
rl_music_update                         dropped  audio is mixed by the runtime; no per-stream update
rl_music_update_all                     dropped  audio is mixed by the runtime; no per-stream update

